// Arma la fila de memoria de esta sesión (solo datos estructurados, nunca la conversación)
const chat = $('Datos limpios del email').first().json;
let prev = {};
try { prev = $('Contexto · Usuario recurrente').first().json; } catch (e) { prev = {}; }
let lead = {}, intencion = '';
// salida 0 = rama de éxito del Router (la salida 1 es la rama de error)
try { const o = ($('Router de Intención').all(0)[0] || {}).json?.output || {}; lead = o.datos_lead || {}; intencion = o.intencion || ''; } catch (e) {}
let estadoFinal = '';
try { estadoFinal = $('Consolidar Respuesta').first().json.status_final || ''; } catch (e) {}
let datos = {};
try { datos = JSON.parse(prev.datos_clave || '{}'); } catch (e) { datos = {}; }
for (const [k, v] of Object.entries(lead)) {
  if (v !== '' && v !== null && v !== undefined && v !== 0) datos[k] = v;
}
const fila = {
  'Session_ID': chat.sessionId,
  'Nombre': datos.contacto || '',
  'Estado del caso': [intencion, estadoFinal].filter(Boolean).join(' · ') || prev.status || 'Nuevo',
  'Resumen consolidado': prev.resumen_json || '',
  'Datos clave': JSON.stringify(datos),
  'Cantidad de mensajes': (Number(prev.mensajes) || 0) + 1,
  'Fecha de actualización': $now.setZone('America/Argentina/Buenos_Aires').toFormat('dd/MM/yyyy HH:mm'),
};
return [{ json: fila }];

// Convierte los mensajes de la memoria de corto plazo en texto plano para el resumidor
const out = [];
const fmt = (m) => {
  if (!m || typeof m !== 'object') return String(m ?? '');
  const parts = [];
  if (m.human) parts.push('Usuario: ' + m.human);
  if (m.ai) parts.push('Asistente: ' + m.ai);
  if (parts.length) return parts.join('\n');
  const tipo = m.type || m.id?.[2] || m.role || '';
  const txt = m.content ?? m.kwargs?.content ?? m.data?.content ?? m.text;
  if (txt !== undefined) return (/human|user/i.test(tipo) ? 'Usuario: ' : 'Asistente: ') + txt;
  return JSON.stringify(m);
};
for (const it of $input.all()) {
  const j = it.json;
  if (Array.isArray(j.messages)) j.messages.forEach(m => out.push(fmt(m)));
  else out.push(fmt(j));
}
return [{ json: { historial: out.filter(Boolean).join('\n').slice(0, 12000) } }];

