// Sobrescribe el resumen anterior con el nuevo objeto JSON (idempotente: misma fila por Session_ID)
const fila = { ...$('Preparar memoria').first().json };
const o = $json.output;
if (o && o.asunto_principal) {
  fila['Resumen consolidado'] = JSON.stringify({
    asunto_principal: String(o.asunto_principal),
    puntos_clave: Array.isArray(o.puntos_clave) ? o.puntos_clave.map(String) : [],
    accion_requerida: String(o.accion_requerida || 'Ninguna'),
  });
}
return [{ json: fila }];
